const imageCache=new Map();
function ProductImage({product}){const [src,setSrc]=useState(typeof product.img==="string"&&product.img.startsWith("http")?product.img:"");const [loaded,setLoaded]=useState(false);
useEffect(()=>{let cancelled=false;const key=product.n+"|"+product.b+"|"+product.salt;const url=imageCache.get(key)||productImages[product.n]||("/api/product-image?name="+encodeURIComponent(product.n)+"&brand="+encodeURIComponent(product.b)+"&salt="+encodeURIComponent(product.salt));imageCache.set(key,url);const el=document.getElementById("product-image-"+String(product.id));if(!el)return;const load=()=>{if(!cancelled){setSrc(url);setLoaded(true)}};const obs=new IntersectionObserver(entries=>{if(entries.some(x=>x.isIntersecting)){load();obs.disconnect()}},{rootMargin:"500px"});obs.observe(el);return()=>{cancelled=true;obs.disconnect()};},[product.id,product.n,product.b,product.salt]);
return <div id={"product-image-"+String(product.id)} className="productImageInner">{src&&loaded?<img src={src} alt={product.n} loading="lazy" referrerPolicy="no-referrer" onError={()=>{setLoaded(false);setSrc("")}}/>:product.img}</div>}
