 useEffect(()=>{const locked=menu||!!panel;if(!locked)return;const body=document.body,html=document.documentElement;const prevBody=body.style.overflow,prevHtml=html.style.overscrollBehavior;body.style.overflow="hidden";html.style.overscrollBehavior="none";return()=>{body.style.overflow=prevBody;html.style.overscrollBehavior=prevHtml}},[menu,panel]);
