   const init=async()=>{try{const code=new URLSearchParams(window.location.search).get("code");if(code){const{error}=await supabase.auth.exchangeCodeForSession(code);if(error){setError("Google login failed: "+error.message);return}window.history.replaceState({},document.title,window.location.pathname+window.location.hash)}const{data,error}=await supabase.auth.getSession();if(error)setError(error.message);await finishAuth(data.session)}catch(e){setError("Google login failed: "+(e?.message||String(e)))}};init();
   const{data}=supabase.auth.onAuthStateChange(async(e,s)=>{if(e==="SIGNED_IN"||e==="INITIAL_SESSION"||e==="TOKEN_REFRESHED")await finishAuth(s);else if(e==="SIGNED_OUT"){setSession(null);setCart([])}});
