 function toggleWish(p){setWishlist(w=>w.some(x=>x.id===p.id)?w.filter(x=>x.id!==p.id):[...w,p])}
 async function add(p){if(!session){setLogin(true);return}const q=(cart.find(x=>x.id===p.id)?.qty||0)+1;const{error}=await supabase.from("cart_items").upsert({user_id:session.user.id,product_id:p.id,quantity:q},{onConflict:"user_id,product_id"});if(error)setError(error.message);else setCart(c=>{const old=c.find(x=>x.id===p.id);return old?c.map(x=>x.id===p.id?{...x,qty:q}:x):[...c,{...p,qty:1}]})}
 async function change(p,d){const old=cart.find(x=>x.id===p.id);if(!old)return;const q=old.qty+d;if(q<=0){await supabase.from("cart_items").delete().eq("user_id",session.user.id).eq("product_id",p.id);setCart(c=>c.filter(x=>x.id!==p.id))}else{await supabase.from("cart_items").update({quantity:q}).eq("user_id",session.user.id).eq("product_id",p.id);setCart(c=>c.map(x=>x.id===p.id?{...x,qty:q}:x))}}
 async function google(){setBusy(true);setError("");const{error}=await googleLogin();if(error){setError(error.message);setBusy(false)}}
 async function send(){setBusy(true);const n=phone.trim().startsWith("+")?phone.trim():"+91"+phone.replace(/\D/g,"");const{error}=await sendPhoneOtp(n);if(error)setError(error.message);else{setPhone(n);setOtpSent(true)}setBusy(false)}
 async function verify(){setBusy(true);const{data,error}=await verifyPhoneOtp(phone,otp.trim());if(error)setError(error.message);else{setSession(data.session);setLogin(false);setOtpSent(false);await loadCart(data.session.user.id);loadOrders(data.session.user.id);await loadAddresses(data.session.user.id)}setBusy(false)}
 async function uploadPrescription(){if(!session){setLogin(true);return}if(!rxFile)return setError("Choose a prescription file first.");if(rxFile.size>5*1024*1024)return setError("Prescription must be 5 MB or smaller.");setBusy(true);setError("");const ext=(rxFile.name.split(".").pop()||"bin").toLowerCase();const path=session.user.id+"/"+Date.now()+"."+ext;const up=await supabase.storage.from("prescriptions").upload(path,rxFile,{contentType:rxFile.type,upsert:false});if(up.error){setError(up.error.message);setBusy(false);return}const ins=await supabase.from("prescriptions").insert({user_id:session.user.id,storage_path:path,status:"pending",branch_id:branch||null});if(ins.error){await supabase.storage.from("prescriptions").remove([path]);setError(ins.error.message)}else{setMessage("Prescription uploaded · pharmacy review pending");setRx(false);setRxFile(null)}setBusy(false)}
 async function order(){if(!session){setLogin(true);return}if(!branch)return setError("Select a store first.");if(method==="delivery"&&!address)return setError("Select a delivery address.");setBusy(true);setError("");const{data,error}=await supabase.rpc("create_customer_order",{p_branch_id:branch,p_fulfillment_method:method,p_address_id:method==="delivery"?address:null,p_payment_method:payment});if(error)setError(error.message);else{setCheckout(false);setCart([]);await loadOrders(session.user.id);setMessage("Order placed successfully · #"+String(data).slice(0,8))}setBusy(false)}
 async function logout(){await signOut();setLogin(false);setCart([]);setPanel(null)} function openPanel(name){setMenu(false);setPanel(name)} const ADMIN_WHATSAPP="917088252556"; const openAdminWhatsApp=(text="Hello Wellcare Medicose Admin, I need help with my order.")=>window.open("https://wa.me/"+ADMIN_WHATSAPP+"?text="+encodeURIComponent(text),"_blank","noopener,noreferrer"); const shareOrder=(o)=>openAdminWhatsApp("Hello Wellcare Medicose Admin, I want to share my order.\nOrder #"+String(o.id).slice(0,8).toUpperCase()+"\nAmount: ₹"+o.total+"\nStatus: "+String(o.status||"received").replaceAll("_"," ")); function brandMark(name){return name.replace(/[^A-Za-z]/g,"").slice(0,2).toUpperCase()||"WC"} const related=detail?products.filter(x=>x.id!==detail.id&&(x.b===detail.b||x.c===detail.c||x.salt===detail.salt)).slice(0,6):[]
 const shown=useMemo(()=>products.filter(p=>(!cat||p.c===cat)&&(!search||((p.n+" "+p.b+" "+p.salt).toLowerCase().includes(search.toLowerCase())))),[search,cat,products]);
